package com.helpdesk.util;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;

/**
 * Singleton database connection helper for MySQL using JDBC.
 */
public class DBConnection {
    // Database connection details
    private static final String URL = "jdbc:mysql://localhost:3306/helpdesk_db?useSSL=false&serverTimezone=UTC&allowPublicKeyRetrieval=true";
    private static final String USER = "root";
    private static final String PASSWORD = "password";

    // Load JDBC Driver class
    static {
        try {
            Class.forName("com.mysql.cj.jdbc.Driver");
        } catch (ClassNotFoundException e) {
            System.err.println("Error: MySQL Connector Driver not found.");
            e.printStackTrace();
        }
    }

    /**
     * Establishes and returns a connection to the MySQL database.
     * @return Connection object
     * @throws SQLException if a database access error occurs
     */
    public static Connection getConnection() throws SQLException {
        return DriverManager.getConnection(URL, USER, PASSWORD);
    }
}

package com.helpdesk.util;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

/**
 * Utility class for secure password hashing and verification using SHA-256.
 * Note: For production systems, standard bcrypt, scrypt, or PBKDF2 must be used.
 */
public class PasswordHasher {

    /**
     * Hashes a raw text password using SHA-256 with a local pepper.
     * @param password Raw password text
     * @return Base64 encoded hash string
     */
    public static String hashPassword(String password) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(password.getBytes());
            return Base64.getEncoder().encodeToString(hash);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Error: Hashing algorithm SHA-256 not found.", e);
        }
    }

    /**
     * Compares a raw input password against a stored hashed value.
     * @param rawPassword Raw password input
     * @param storedHash Hashed password stored in the database
     * @return true if matches, false otherwise
     */
    public static boolean verifyPassword(String rawPassword, String storedHash) {
        if (rawPassword == null || storedHash == null) {
            return false;
        }
        return hashPassword(rawPassword).equals(storedHash);
    }
}

package com.helpdesk.model;

import java.sql.Timestamp;

/**
 * Model class representing a User entity.
 */
public class User {
    private int userId;
    private int roleId;
    private String firstName;
    private String lastName;
    private String email;
    private String passwordHash;
    private String status;
    private Timestamp createdAt;
    private Timestamp updatedAt;

    public User() {}

    public User(int userId, int roleId, String firstName, String lastName, String email, String passwordHash, String status) {
        this.userId = userId;
        this.roleId = roleId;
        this.firstName = firstName;
        this.lastName = lastName;
        this.email = email;
        this.passwordHash = passwordHash;
        this.status = status;
    }

    public int getUserId() { return userId; }
    public void setUserId(int userId) { this.userId = userId; }

    public int getRoleId() { return roleId; }
    public void setRoleId(int roleId) { this.roleId = roleId; }

    public String getFirstName() { return firstName; }
    public void setFirstName(String firstName) { this.firstName = firstName; }

    public String getLastName() { return lastName; }
    public void setLastName(String lastName) { this.lastName = lastName; }

    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }

    public String getPasswordHash() { return passwordHash; }
    public void setPasswordHash(String passwordHash) { this.passwordHash = passwordHash; }

    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }

    public Timestamp getCreatedAt() { return createdAt; }
    public void setCreatedAt(Timestamp createdAt) { this.createdAt = createdAt; }

    public Timestamp getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(Timestamp updatedAt) { this.updatedAt = updatedAt; }

    @Override
    public String toString() {
        return "User{" +
                "userId=" + userId +
                ", roleId=" + roleId +
                ", firstName='" + firstName + '\'' +
                ", lastName='" + lastName + '\'' +
                ", email='" + email + '\'' +
                ", status='" + status + '\'' +
                '}';
    }
}

package com.helpdesk.model;

import java.sql.Timestamp;

/**
 * Model class representing a Ticket entity.
 */
public class Ticket {
    private int ticketId;
    private String title;
    private String description;
    private String status;
    private String priority;
    private int requesterId;
    private Integer agentId; // Can be null
    private int categoryId;
    private int slaPolicyId;
    private Timestamp slaResponseDeadline;
    private Timestamp slaResolutionDeadline;
    private Timestamp createdAt;
    private Timestamp updatedAt;

    public Ticket() {}

    public Ticket(String title, String description, int requesterId, int categoryId, int slaPolicyId) {
        this.title = title;
        this.description = description;
        this.status = "new";
        this.priority = "medium";
        this.requesterId = requesterId;
        this.categoryId = categoryId;
        this.slaPolicyId = slaPolicyId;
    }

    public int getTicketId() { return ticketId; }
    public void setTicketId(int ticketId) { this.ticketId = ticketId; }

    public String getTitle() { return title; }
    public void setTitle(String title) { this.title = title; }

    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }

    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }

    public String getPriority() { return priority; }
    public void setPriority(String priority) { this.priority = priority; }

    public int getRequesterId() { return requesterId; }
    public void setRequesterId(int requesterId) { this.requesterId = requesterId; }

    public Integer getAgentId() { return agentId; }
    public void setAgentId(Integer agentId) { this.agentId = agentId; }

    public int getCategoryId() { return categoryId; }
    public void setCategoryId(int categoryId) { this.categoryId = categoryId; }

    public int getSlaPolicyId() { return slaPolicyId; }
    public void setSlaPolicyId(int slaPolicyId) { this.slaPolicyId = slaPolicyId; }

    public Timestamp getSlaResponseDeadline() { return slaResponseDeadline; }
    public void setSlaResponseDeadline(Timestamp slaResponseDeadline) { this.slaResponseDeadline = slaResponseDeadline; }

    public Timestamp getSlaResolutionDeadline() { return slaResolutionDeadline; }
    public void setSlaResolutionDeadline(Timestamp slaResolutionDeadline) { this.slaResolutionDeadline = slaResolutionDeadline; }

    public Timestamp getCreatedAt() { return createdAt; }
    public void setCreatedAt(Timestamp createdAt) { this.createdAt = createdAt; }

    public Timestamp getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(Timestamp updatedAt) { this.updatedAt = updatedAt; }

    @Override
    public String toString() {
        return "Ticket{" +
                "ticketId=" + ticketId +
                ", title='" + title + '\'' +
                ", status='" + status + '\'' +
                ", priority='" + priority + '\'' +
                ", requesterId=" + requesterId +
                ", agentId=" + agentId +
                ", categoryId=" + categoryId +
                ", slaPolicyId=" + slaPolicyId +
                '}';
    }
}

package com.helpdesk.service;

import com.helpdesk.model.User;
import com.helpdesk.util.DBConnection;
import com.helpdesk.util.PasswordHasher;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

/**
 * Service handling user login and authentication verification against MySQL database.
 */
public class AuthService {

    /**
     * Authenticates a user using email and password.
     * @param email User email
     * @param password Plaintext password
     * @return User object if authentication is successful, null otherwise
     */
    public User authenticate(String email, String password) {
        if (email == null || password == null) {
            return null;
        }

        String query = "SELECT * FROM users WHERE email = ? AND status = 'active'";

        try (Connection conn = DBConnection.getConnection();
             PreparedStatement pstmt = conn.prepareStatement(query)) {

            pstmt.setString(1, email);

            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    String storedHash = rs.getString("password_hash");

                    // Verify plaintext password against DB SHA-256 hash
                    if (PasswordHasher.verifyPassword(password, storedHash)) {
                        User user = new User();
                        user.setUserId(rs.getInt("user_id"));
                        user.setRoleId(rs.getInt("role_id"));
                        user.setFirstName(rs.getString("first_name"));
                        user.setLastName(rs.getString("last_name"));
                        user.setEmail(rs.getString("email"));
                        user.setPasswordHash(storedHash);
                        user.setStatus(rs.getString("status"));
                        user.setCreatedAt(rs.getTimestamp("created_at"));
                        user.setUpdatedAt(rs.getTimestamp("updated_at"));
                        return user;
                    }
                }
            }
        } catch (SQLException e) {
            System.err.println("Database error during user authentication: " + e.getMessage());
            e.printStackTrace();
        }
        return null; // Auth failed or exception occurred
    }
}

package com.helpdesk.service;

import com.helpdesk.model.Ticket;
import com.helpdesk.util.DBConnection;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.sql.Timestamp;

/**
 * Service handling ticket creation operations in the MySQL database.
 */
public class TicketService {

    /**
     * Creates a new support ticket and dynamically computes SLA deadlines.
     * @param ticket Ticket object containing basic details (title, description, requester, category, priority, policy)
     * @return Fully populated Ticket object including generated ID and SLA deadlines, or null on failure
     */
    public Ticket createTicket(Ticket ticket) {
        String sql = "INSERT INTO tickets (title, description, status, priority, requester_id, agent_id, category_id, sla_policy_id, sla_response_deadline, sla_resolution_deadline) " +
                     "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

        try (Connection conn = DBConnection.getConnection()) {
            // Start transaction
            conn.setAutoCommit(false);

            try {
                // 1. Calculate SLA deadlines dynamically based on the policy rules
                calculateAndSetSla(conn, ticket);

                // 2. Perform Insert statement
                try (PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
                    pstmt.setString(1, ticket.getTitle());
                    pstmt.setString(2, ticket.getDescription());
                    pstmt.setString(3, ticket.getStatus() != null ? ticket.getStatus() : "new");
                    pstmt.setString(4, ticket.getPriority() != null ? ticket.getPriority() : "medium");
                    pstmt.setInt(5, ticket.getRequesterId());

                    if (ticket.getAgentId() != null) {
                        pstmt.setInt(6, ticket.getAgentId());
                    } else {
                        pstmt.setNull(6, java.sql.Types.INTEGER);
                    }

                    pstmt.setInt(7, ticket.getCategoryId());
                    pstmt.setInt(8, ticket.getSlaPolicyId());
                    pstmt.setTimestamp(9, ticket.getSlaResponseDeadline());
                    pstmt.setTimestamp(10, ticket.getSlaResolutionDeadline());

                    int affectedRows = pstmt.executeUpdate();
                    if (affectedRows == 0) {
                        throw new SQLException("Creating ticket failed, no rows affected.");
                    }

                    // Retrieve generated Primary Key ID
                    try (ResultSet generatedKeys = pstmt.getGeneratedKeys()) {
                        if (generatedKeys.next()) {
                            ticket.setTicketId(generatedKeys.getInt(1));
                        } else {
                            throw new SQLException("Creating ticket failed, no ID obtained.");
                        }
                    }
                }

                // Commit transaction
                conn.commit();
                return ticket;

            } catch (SQLException e) {
                // Rollback on any failure
                conn.rollback();
                throw e;
            }
        } catch (SQLException e) {
            System.err.println("Database error during ticket creation: " + e.getMessage());
            e.printStackTrace();
        }
        return null;
    }

    /**
     * Helper method to lookup configured SLA policy hours and calculate dynamic deadlines.
     */
    private void calculateAndSetSla(Connection conn, Ticket ticket) throws SQLException {
        String policySql = "SELECT response_time_hours, resolution_time_hours FROM sla_policies WHERE sla_policy_id = ?";

        try (PreparedStatement pstmt = conn.prepareStatement(policySql)) {
            pstmt.setInt(1, ticket.getSlaPolicyId());

            try (ResultSet rs = pstmt.executeQuery()) {
                long nowMs = System.currentTimeMillis();
                int responseHours = 8;     // Default fallback
                int resolutionHours = 24;  // Default fallback

                if (rs.next()) {
                    responseHours = rs.getInt("response_time_hours");
                    resolutionHours = rs.getInt("resolution_time_hours");
                }

                // Compute milliseconds (1 hour = 3,600,000 ms)
                ticket.setSlaResponseDeadline(new Timestamp(nowMs + (responseHours * 3600000L)));
                ticket.setSlaResolutionDeadline(new Timestamp(nowMs + (resolutionHours * 3600000L)));
            }
        }
    }
}

